import{_ as i,C as r,o as l,c as s,j as e,a as d,E as o,a5 as n}from"./chunks/framework.Dep_XxFZ.js";const C=JSON.parse('{"title":"右键菜单","description":"","frontmatter":{},"headers":[],"relativePath":"components/context-menu.md","filePath":"components/context-menu.md","lastUpdated":1787385783000}'),h={name:"components/context-menu.md"},u={id:"右键菜单",tabindex:"-1"};function p(x,t,m,b,g,f){const a=r("Badge"),c=r("XhDemo");return l(),s("div",null,[e("h1",u,[t[0]||(t[0]=d("右键菜单 ",-1)),o(a,{type:"info",text:"context-menu"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#右键菜单","aria-label":'Permalink to "右键菜单 <Badge type="info" text="context-menu" />"'},"​",-1))]),t[3]||(t[3]=n('<p>在触发区上右键（触摸端长按）弹出的命令菜单，钉在按下去的那一点上。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>一个对象上有多个针对它的命令，且界面上没有位置全部摆出来（表格行、画布节点、文件项）。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>命令是主要路径：右键是隐藏入口，新用户找不到。主要动作要有可见的按钮。</li><li>触摸端是主要场景：长按有学习成本，且与系统手势冲突。</li><li>要选一个值而不是执行命令：用<a href="./select">选择器</a>或<a href="./popselect">弹出选择</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>offset</code> 默认 0——右键菜单要贴着光标。</li><li>支持分组、标记位、分隔线与二级子菜单；任意层级选中都发根的 <code>select</code> 并整链关闭。</li><li><code>typeahead</code> 决定展开后的可打印字符是拿去检索还是放行给页面。</li><li><code>longPressDelay</code> 是触摸端按住多久算触发。</li><li><code>root</code> 的插槽给出锚点坐标与 <code>openAt</code>，可以从任意位置弹出。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>在触发区上右键（触摸端长按），菜单钉在按下去的那一点上</p>',10)),o(c,{src:"context-menu/01-basic"}),t[4]||(t[4]=e("h3",{id:"分组与标记位",tabindex:"-1"},[d("分组与标记位 "),e("a",{class:"header-anchor",href:"#分组与标记位","aria-label":'Permalink to "分组与标记位"'},"​")],-1)),t[5]||(t[5]=e("p",null,"group 用 value 跟自己的 group-label 配对，item-indicator 是纯装饰的勾选位",-1)),o(c,{src:"context-menu/02-group"}),t[6]||(t[6]=e("h3",{id:"受控与锚点",tabindex:"-1"},[d("受控与锚点 "),e("a",{class:"header-anchor",href:"#受控与锚点","aria-label":'Permalink to "受控与锚点"'},"​")],-1)),t[7]||(t[7]=e("p",null,"传了 open 就由宿主说了算；root 的插槽给出锚点坐标与 openAt，可以从任意位置弹出",-1)),o(c,{src:"context-menu/03-controlled"}),t[8]||(t[8]=e("h3",{id:"语气",tabindex:"-1"},[d("语气 "),e("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[9]||(t[9]=e("p",null,"tone 决定条目高亮与标记位用哪族颜色；高亮静止态看不出来，右键弹出后悬停条目、或用方向键把焦点移上去才显现",-1)),o(c,{src:"context-menu/04-tone"}),t[10]||(t[10]=e("h3",{id:"尺寸",tabindex:"-1"},[d("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[11]||(t[11]=e("p",null,"size 换的是条目的内边距、间距与字号；三档各挂一块触发区，逐块右键对比",-1)),o(c,{src:"context-menu/05-size"}),t[12]||(t[12]=e("h3",{id:"放置位与箭头",tabindex:"-1"},[d("放置位与箭头 "),e("a",{class:"header-anchor",href:"#放置位与箭头","aria-label":'Permalink to "放置位与箭头"'},"​")],-1)),t[13]||(t[13]=e("p",null,"placement 是相对光标那一点的首选位，offset 把浮层从光标推开；arrow 指回那一点",-1)),o(c,{src:"context-menu/06-placement"}),t[14]||(t[14]=e("h3",{id:"条目里的图标与快捷键",tabindex:"-1"},[d("条目里的图标与快捷键 "),e("a",{class:"header-anchor",href:"#条目里的图标与快捷键","aria-label":'Permalink to "条目里的图标与快捷键"'},"​")],-1)),t[15]||(t[15]=e("p",null,"item-text 只是文字那一段，图标与快捷键提示作为兄弟节点排在它两侧",-1)),o(c,{src:"context-menu/07-icon"}),t[16]||(t[16]=e("h3",{id:"触发与连打",tabindex:"-1"},[d("触发与连打 "),e("a",{class:"header-anchor",href:"#触发与连打","aria-label":'Permalink to "触发与连打"'},"​")],-1)),t[17]||(t[17]=e("p",null,"longPressDelay 是触摸端按住多久算触发；typeahead 决定展开后的可打印字符是拿去检索还是放行给页面",-1)),o(c,{src:"context-menu/08-trigger"}),t[18]||(t[18]=e("h3",{id:"二级子菜单",tabindex:"-1"},[d("二级子菜单 "),e("a",{class:"header-anchor",href:"#二级子菜单","aria-label":'Permalink to "二级子菜单"'},"​")],-1)),t[19]||(t[19]=e("p",null,"XhContextMenuSub 在右键菜单里嵌一台子菜单：触发条目双重身份（父层方向键照常走、右方向键进子层），子层内用 XhMenu 系部件，任意层级选中都发根的 select 并整链关闭",-1)),o(c,{src:"context-menu/09-submenu"}),t[20]||(t[20]=n('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-context-menu&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhContextMenuArrow</code> <code>XhContextMenuContent</code> <code>XhContextMenuGroup</code> <code>XhContextMenuGroupLabel</code> <code>XhContextMenuItem</code> <code>XhContextMenuItemIndicator</code> <code>XhContextMenuItemText</code> <code>XhContextMenuPositioner</code> <code>XhContextMenuRoot</code> <code>XhContextMenuSeparator</code> <code>XhContextMenuSub</code> <code>XhContextMenuSubTrigger</code> <code>XhContextMenuTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useContextMenu</code></td></tr><tr><td>状态机</td><td><code>contextMenuMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/context-menu.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;context-menu&quot;</code>：<code>root</code> · <strong><code>trigger</code></strong> · <code>positioner</code> · <strong><code>content</code></strong> · <strong><code>item</code></strong> · <code>item-text</code> · <code>item-indicator</code> · <code>separator</code> · <code>group</code> · <code>group-label</code> · <code>arrow</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>ContextMenuNode[]</code></td><td></td><td>条目数据，显示文本、禁用、标记位与分组的事实源。给了它，条目部件只需报 value。 缺省即回到「文本与禁用全写在条目部件上」的老路。</td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td>展开态。给定即受控：内部不再自改，只发 onOpenChange。</td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>placement</code></td><td><code>Placement</code></td><td></td><td>相对光标那一点的首选放置位，默认 bottom-start。</td></tr><tr><td><code>offset</code></td><td><code>number</code></td><td></td><td>浮层与光标的间距（px），默认 0——右键菜单要贴着光标。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>方向键走到尽头是否回绕，默认 true。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr。</td></tr><tr><td><code>typeahead</code></td><td><code>boolean</code></td><td></td><td>连打检索，默认开。关掉后可打印字符一律放行给页面。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ContextMenuTranslations&gt;</code></td><td></td><td>读屏用的文案，默认英文。</td></tr><tr><td><code>longPressDelay</code></td><td><code>number</code></td><td></td><td>触摸端长按多久算触发（ms），默认 700。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定条目高亮与标记位用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定条目高度、内边距与字号档位。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: ContextMenuOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控时随内部转移一并通知。</td></tr><tr><td><code>onSelect</code></td><td><code>(details: ContextMenuSelectDetails) =&gt; void</code></td><td></td><td>条目被选中；菜单随之关闭。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>ContextMenuOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr><tr><td><code>select</code></td><td><code>ContextMenuSelectDetails</code></td><td>条目被选中（菜单随之关闭）；detail 为 <code>{ value: string }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhContextMenuRoot</code></td><td><code>default</code></td><td><code>ContextMenuRootSlotProps</code></td><td></td></tr><tr><td><code>XhContextMenuRoot</code></td><td><code>trigger</code></td><td>—</td><td></td></tr><tr><td><code>XhContextMenuRoot</code></td><td><code>item</code></td><td><code>ContextMenuNodeMeta</code></td><td></td></tr><tr><td><code>XhContextMenuSub</code></td><td><code>default</code></td><td><code>ContextMenuSubSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>closed</code> · <code>pressing</code> · <code>open</code></p><p><strong>事件</strong>：<code>CONTEXT.MENU</code> · <code>OPEN</code> · <code>CLOSE</code> · <code>PRESS.START</code> · <code>PRESS.MOVE</code> · <code>PRESS.END</code> · <code>after.longPressDelay</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code> · <code>ITEM.FOCUS</code> · <code>FOCUS.CLEAR</code> · <code>ITEM.LOST</code> · <code>ITEM.SELECT</code></p><p><strong>判据</strong>：<code>isOpenControlled</code> · <code>movedBeyondTolerance</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useContextMenu</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>collection</code></td><td><code>readonly ContextMenuNodeMeta[]</code></td><td>collection 推出的条目元信息，按数据顺序排列；没给 collection 即空数组。</td></tr><tr><td><code>pressing</code></td><td><code>boolean</code></td><td>长按计时进行中；触发区据此给按压反馈。</td></tr><tr><td><code>point</code></td><td><code>ContextMenuPoint | null</code></td><td>当前锚点坐标；一次都没打开过时为 null。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点锚点；收起时为 null。</td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td>收起走 CLOSE；展开沿用最近一次锚点坐标，从未有过坐标时锚在触发区的起始角上。</td></tr><tr><td><code>openAt</code></td><td><code>(x: number, y: number) =&gt; void</code></td><td>命令式展开到指定视口坐标。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: ContextMenuItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: ContextMenuItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemIndicatorProps</code></td><td><code>(props: ContextMenuItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSeparatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGroupProps</code></td><td><code>(props: ContextMenuGroupProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGroupLabelProps</code></td><td><code>(props: ContextMenuGroupProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getArrowProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/menu/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ContextMenu</code> / <code>Shift+F10</code></td><td>focus in trigger</td><td>在触发区起始角展开菜单并把焦点落到首个可用条目</td></tr><tr><td><code>ArrowDown</code></td><td>open, focus in content</td><td>焦点移到下一个条目（禁用项跳过、尽头按 loop 回绕）</td></tr><tr><td><code>ArrowUp</code></td><td>open, focus in content</td><td>焦点移到上一个条目（禁用项跳过、尽头按 loop 回绕）</td></tr><tr><td><code>Home</code></td><td>open, focus in content</td><td>焦点移到首个可用条目</td></tr><tr><td><code>End</code></td><td>open, focus in content</td><td>焦点移到末个可用条目</td></tr><tr><td><code>单个可打印字符</code></td><td>open, typeahead 未关</td><td>连打检索把焦点移到首字母匹配的条目，不选中它</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in item, not disabled</td><td>派发选中详情并关闭菜单，焦点归还触发区</td></tr><tr><td><code>Escape</code></td><td>open</td><td>关闭菜单并把焦点归还触发区</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>open</td><td>关闭菜单，焦点不归还触发区，按 Tab 序列自然离开</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-haspopup</code></td><td>&#39;menu&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-keyshortcuts</code></td><td>&#39;Shift+F10&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-label</code></td><td>props.translations.content</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;menu&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;menuitem&#39;</td></tr><tr><td><code>item-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>separator</code></td><td><code>aria-orientation</code></td><td>&#39;horizontal&#39;</td></tr><tr><td><code>separator</code></td><td><code>role</code></td><td>&#39;separator&#39;</td></tr><tr><td><code>group</code></td><td><code>aria-labelledby</code></td><td><code>group-label</code> 部件的 id</td></tr><tr><td><code>group</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>arrow</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/context-menu.css</code> 按部件选择：<code>[data-scope=&quot;context-menu&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>trigger</code></td><td><code>data-pressing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-hidden</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>content</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>arrow</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-context-menu-arrow-size</code> · <code>--xh-context-menu-bg</code> · <code>--xh-context-menu-border</code> · <code>--xh-context-menu-fg</code> · <code>--xh-context-menu-group-label-fg</code> · <code>--xh-context-menu-group-label-font-size</code> · <code>--xh-context-menu-group-label-font-weight</code> · <code>--xh-context-menu-group-label-px</code> · <code>--xh-context-menu-group-label-py</code> · <code>--xh-context-menu-icon-size</code> · <code>--xh-context-menu-item-active-font-weight</code> · <code>--xh-context-menu-item-bg-active</code> · <code>--xh-context-menu-item-bg-hover</code> · <code>--xh-context-menu-item-fg</code> · <code>--xh-context-menu-item-font-size</code> · <code>--xh-context-menu-item-gap</code> · <code>--xh-context-menu-item-indicator-fg</code> · <code>--xh-context-menu-item-indicator-size</code> · <code>--xh-context-menu-item-leading</code> · <code>--xh-context-menu-item-px</code> · <code>--xh-context-menu-item-py</code> · <code>--xh-context-menu-item-radius</code> · <code>--xh-context-menu-layer</code> · <code>--xh-context-menu-max-h</code> · <code>--xh-context-menu-max-w</code> · <code>--xh-context-menu-min-w</code> · <code>--xh-context-menu-px</code> · <code>--xh-context-menu-py</code> · <code>--xh-context-menu-radius</code> · <code>--xh-context-menu-separator-color</code> · <code>--xh-context-menu-separator-my</code> · <code>--xh-context-menu-separator-thickness</code> · <code>--xh-context-menu-shadow</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-pop-in</code> · <code>xh-pop-out</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./menu">菜单</a>共用条目部件；子菜单用 <code>XhContextMenuSub</code>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>菜单里的每条命令都要在别处有可见入口，右键只是快捷方式。</li><li>条目控制在十条以内，超过就分组。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>屏蔽浏览器原生右键却不给出等价能力（复制、检查、在新标签打开）。</li><li>把整页都做成右键触发区，用户再也用不了浏览器菜单。</li></ul>',48))])}const q=i(h,[["render",p]]);export{C as __pageData,q as default};
